import AppKit
import HexpadKit

/// Tools > Document Summary… (V19h): document statistics in a read-only sheet
/// with a copyable report. The Tools item is the dialog's single home; the
/// menu title carries the HIG ellipsis while the sheet title does not (Pilot
/// P-08).
///
/// The report is generated by the pure, testable ``summaryReport(activeController:)``
/// function so tests can assert its contents without spinning up AppKit UI
/// (the panel is the only untested seam), matching the DebugInfoWindowController
/// pattern.
final class SummaryWindowController {

    /// Builds the full Summary report from the active controller's document.
    ///
    /// `activeController` may be `nil` (no window / headless host); every
    /// session field then degrades to a safe "(none)" value rather than
    /// crashing. The statistics come from the authoritative model
    /// (`DocumentModel`), the line count from the gutter's shared convention
    /// (`GutterGeometry.lineCount`), and the selection from the focused
    /// editor's live selection.
    static func summaryReport(activeController: MainWindowController?) -> String {
        let doc = activeController?.tabStore.selectedDocument
        let text = doc?.text ?? ""
        let selection = activeController?.editorTextView?.selectedRange
            ?? NSRange(location: 0, length: 0)
        let selectionActive = selection.length > 0
        let selectedText = selectionActive ? (text as NSString).substring(with: selection) : ""
        let selectionLineSpan = selectionActive
            ? selectedText.components(separatedBy: "\n").count - 1 + 1
            : 0

        let stamps = fileTimestamps(for: doc?.filePath)

        var lines: [String] = []
        lines.append("File: \(doc?.name ?? "(none)")")
        if let path = doc?.filePath?.path {
            lines.append("Path: \(path)")
        } else {
            lines.append("Path: \(doc == nil ? "(none)" : "(untitled)")")
        }
        lines.append("Created: \(timestampString(stamps.created))")
        lines.append("Modified: \(timestampString(stamps.modified))")
        lines.append("Accessed: \(timestampString(stamps.accessed))")
        // The doc's Characters row excludes EOLs (TextEdit convention). Keep
        // the raw count as a separate row so nothing that needed it loses it.
        lines.append("Characters: \(Self.characterCount(excludingEOLs: text))")
        lines.append("Characters (with EOLs): \(text.count)")
        lines.append("Bytes: \(onDiskByteCount(of: doc))")
        if let size = fileSizeOnDisk(of: doc) {
            lines.append("Size on disk: \(size) bytes")
        }
        lines.append("Lines: \(doc == nil ? 0 : GutterGeometry.lineCount(in: text))")
        lines.append("Selection: \(selectionActive ? selection.length : 0) chars, \(selectionLineSpan) lines")
        lines.append("Words: \(text.split(whereSeparator: \.isWhitespace).count)")
        lines.append("Encoding: \(doc?.encoding ?? "(none)")")
        lines.append("EOL: \(doc?.eolType ?? "(none)")")
        lines.append("Type: \(doc?.language ?? "(none)")")
        return lines.joined(separator: "\n")
    }

    /// Characters excluding line breaks. A CRLF pair is one `Character` in
    /// Swift, so filtering by `isNewline` handles LF, CRLF and CR alike.
    static func characterCount(excludingEOLs text: String) -> Int {
        text.filter { !$0.isNewline }.count
    }

    /// "-" for untitled or unreadable files, otherwise a stable POSIX stamp.
    static func timestampString(_ date: Date?) -> String {
        guard let date else { return "-" }
        let formatter = DateFormatter()
        formatter.locale = Locale(identifier: "en_US_POSIX")
        formatter.dateFormat = "yyyy-MM-dd HH:mm:ss"
        return formatter.string(from: date)
    }

    /// Created/modified come from `FileManager`'s item attributes. macOS does
    /// not expose an access date through `attributesOfItem`, so that one is
    /// read from the same file URL's resource values. All three are `nil` for
    /// an untitled document, which the report renders as "-".
    static func fileTimestamps(for url: URL?) -> (created: Date?, modified: Date?, accessed: Date?) {
        guard let url else { return (nil, nil, nil) }
        let attributes = try? FileManager.default.attributesOfItem(atPath: url.path)
        let resources = try? url.resourceValues(forKeys: [.contentAccessDateKey])
        return (attributes?[.creationDate] as? Date,
                attributes?[.modificationDate] as? Date,
                resources?.contentAccessDate)
    }

    /// The file's current on-disk size, which can differ from
    /// ``onDiskByteCount(of:)`` while the buffer is dirty. `nil` for untitled
    /// documents or files that cannot be stat'ed.
    static func fileSizeOnDisk(of doc: DocumentModel?) -> Int? {
        guard let url = doc?.filePath,
              let attributes = try? FileManager.default.attributesOfItem(atPath: url.path),
              let size = attributes[.size] else { return nil }
        return (size as? NSNumber)?.intValue ?? (size as? Int)
    }

    /// The byte count a save of `doc` would write: the document's
    /// `saveEncoding` applied to the text converted back to the document's
    /// `eolType`, plus the BOM when `keepsBOM`. This is `DocumentModel`'s
    /// `encodedData()` computation (private there), replicated so the report
    /// shows what an actual save writes rather than the UTF-8 buffer size.
    static func onDiskByteCount(of doc: DocumentModel?) -> Int {
        guard let doc else { return 0 }
        let encoding = String.Encoding(rawValue: EncodingDetective.nsEncoding(from: doc.saveEncoding))
        var data = EOLDetective.converting(doc.text, to: doc.eolType)
            .data(using: encoding) ?? Data()
        if doc.keepsBOM,
           let bom = EncodingDetective.bomBytes(for: doc.saveEncoding),
           !data.starts(with: bom) {
            data = bom + data
        }
        return data.count
    }

    // MARK: - Dialog

    static func showSummary(activeController: MainWindowController?) {
        presentCopyableAlert(title: "Document Summary",
                             text: summaryReport(activeController: activeController),
                             for: activeController?.view.window)
    }

    /// Read-only report sheet. Prefer an attached sheet on the active window;
    /// the modal fallback keeps callers without a visible window (and older
    /// headless harnesses) working.
    private static func presentCopyableAlert(title: String, text: String, for window: NSWindow?) {
        let alert = NSAlert()
        alert.messageText = title
        alert.informativeText = "Read-only statistics for the active document."
        alert.alertStyle = .informational

        let scrollView = NSScrollView(frame: NSRect(x: 0, y: 0, width: 520, height: 300))
        scrollView.hasVerticalScroller = true
        scrollView.hasHorizontalScroller = false
        scrollView.autohidesScrollers = true
        scrollView.borderType = .bezelBorder

        let textView = NSTextView(frame: scrollView.bounds)
        textView.autoresizingMask = [.width, .height]
        textView.isEditable = false
        textView.isSelectable = true
        textView.font = NSFont.monospacedSystemFont(ofSize: 11, weight: .regular)
        textView.string = text
        scrollView.documentView = textView

        alert.accessoryView = scrollView

        alert.addButton(withTitle: "Copy")
        alert.addButton(withTitle: "Close")

        let finish: (NSApplication.ModalResponse) -> Void = { response in
            guard response == .alertFirstButtonReturn else { return }
            let pasteboard = NSPasteboard.general
            pasteboard.clearContents()
            pasteboard.setString(text, forType: .string)
        }

        if let window, window.isVisible {
            alert.beginSheetModal(for: window, completionHandler: finish)
        } else {
            finish(alert.runModal())
        }
    }
}
